USE SAKILA;

-- 1. List the number of films per category.
SELECT COUNT(fc.film_id) AS number_of_films, c.name AS category_name, fc.category_id FROM sakila.film_category AS fc
JOIN sakila.category AS c
ON fc.category_id=c.category_id
GROUP BY c.name, fc.category_id;

-- 2. Retrieve the store ID, city, and country for each store.
SELECT s.store_id,c.city,co.country FROM sakila.store AS s
JOIN address AS a
ON s.address_id=a.address_id
JOIN city AS c
ON a.city_id =c.city_id 
JOIN country AS co
ON c.country_id=co.country_id;

-- 3. Calculate the total revenue generated by each store in dollars.
SELECT so.store_id, SUM(p.amount) AS total_revenue FROM sakila.store AS so
JOIN staff AS sa
ON so.store_id=sa.store_id
JOIN payment AS p
ON sa.staff_id=p.staff_id
GROUP BY so.store_id;

-- 4. Determine the average running time of films for each category.
SELECT c.name as category_name, AVG(f.length) AS avg_running_time FROM sakila.film AS f
JOIN film_category AS fc 
ON f.film_id=fc.film_id
JOIN category AS c
ON fc.category_id=c.category_id
GROUP BY c.name;

-- BONUS
-- 5.Identify the film categories with the longest average running time.
SELECT c.name AS category_name, AVG(f.length) AS avg_running_time
FROM sakila.film AS f
JOIN sakila.film_category AS fc
ON f.film_id = fc.film_id
JOIN sakila.category AS c
ON fc.category_id = c.category_id
GROUP BY c.name
ORDER BY avg_running_time DESC;

-- 6.Display the top 10 most frequently rented movies in descending order.
SELECT f.title, COUNT(r.rental_id) AS rental_count FROM sakila.film AS f
JOIN sakila.inventory AS i
ON f.film_id = i.film_id
JOIN sakila.rental AS r
ON i.inventory_id = r.inventory_id
GROUP BY f.title
ORDER BY rental_count DESC
LIMIT 10;

-- 7. Determine if "Academy Dinosaur" can be rented from Store 1.
SELECT f.title,
CASE
    WHEN COUNT(i.inventory_id) > 0 THEN 'Available'
    ELSE 'NOT available'
END AS availability_status
FROM sakila.film AS f
LEFT JOIN sakila.inventory AS i
ON f.film_id = i.film_id
AND i.store_id = 1
WHERE f.title = 'Academy Dinosaur'
GROUP BY f.title;

-- 8. Provide a list of all distinct film titles with availability status.
SELECT f.title,
CASE
    WHEN IFNULL(COUNT(i.inventory_id), 0) > 0 THEN 'Available'
    ELSE 'NOT available'
END AS availability_status
FROM sakila.film AS f
LEFT JOIN sakila.inventory AS i
ON f.film_id = i.film_id
GROUP BY f.title
ORDER BY f.title ASC;